import{_ as t,o as e,c as r,a2 as i}from"./chunks/framework.mRCPFc5l.js";const u=JSON.parse('{"title":"真实工程实践","description":"从多应用服务端、PC 管理端、移动 H5 与原生小程序中抽取的可复用工程方法。","frontmatter":{"title":"真实工程实践","description":"从多应用服务端、PC 管理端、移动 H5 与原生小程序中抽取的可复用工程方法。"},"headers":[],"relativePath":"practice/index.md","filePath":"practice/index.md","lastUpdated":1788510053000}'),l={name:"practice/index.md"};function d(c,a,o,n,h,s){return e(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="真实工程实践" tabindex="-1">真实工程实践 <a class="header-anchor" href="#真实工程实践" aria-label="Permalink to &quot;真实工程实践&quot;">​</a></h1><p>这一组文章来自一套长期演进的多端业务系统：服务端承担多个应用入口，客户端同时包含 PC 管理端、移动 H5 和原生小程序。系列不复述具体项目，也不展示私有源码，而是回答更值得复用的问题：边界怎么划、契约怎么稳、故障怎么兜底，以及旧系统怎样在持续交付中逐步变好。</p><blockquote><p>所有示例中的名称、路径、接口、数据结构和业务数值均为重新设计的演示内容。它们用于解释方法，不对应任何真实系统实现。</p></blockquote><h2 id="建议阅读顺序" tabindex="-1">建议阅读顺序 <a class="header-anchor" href="#建议阅读顺序" aria-label="Permalink to &quot;建议阅读顺序&quot;">​</a></h2><h3 id="先建立全局视角" tabindex="-1">先建立全局视角 <a class="header-anchor" href="#先建立全局视角" aria-label="Permalink to &quot;先建立全局视角&quot;">​</a></h3><ol><li><a href="/practice/full-stack-system-map">多端业务系统全景图</a>：不用“仓库清单”描述系统，而是用能力、请求、身份、数据和发布五张图建立共同语言。</li><li><a href="/practice/cross-client-api-contract">跨端 API 契约设计</a>：让 PC、H5、小程序和服务端对成功、失败、身份、幂等与兼容性形成一致约定。</li><li><a href="/practice/legacy-modernization-roadmap">遗留系统渐进式治理路线</a>：不做高风险推倒重来，先收拢变化点，再替换内部实现。</li><li><a href="/practice/public-writing-from-private-code">从私有源码提炼公开文章</a>：建立证据、抽象、示例重写和发布扫描流程，让经验可分享而实现不外泄。</li></ol><h3 id="再深入服务端" tabindex="-1">再深入服务端 <a class="header-anchor" href="#再深入服务端" aria-label="Permalink to &quot;再深入服务端&quot;">​</a></h3><ul><li><a href="/practice/yaf-multi-app-architecture">Yaf 多应用单体的边界与治理</a>：入口、模块、共享模型、基础库和外部集成怎样分工。</li><li><a href="/practice/transactional-business-workflow">高一致性业务工作流</a>：事务、幂等、并发、第三方副作用、补偿和审计如何组合。</li></ul><h3 id="最后看客户端" tabindex="-1">最后看客户端 <a class="header-anchor" href="#最后看客户端" aria-label="Permalink to &quot;最后看客户端&quot;">​</a></h3><ul><li><a href="/practice/vue2-multi-terminal-engineering">Vue 2 多端工程治理</a>：PC 与移动端共存时如何管理路由、状态、组件库、构建和迁移。</li><li><a href="/practice/mobile-h5-reliability">移动 H5 可靠性</a>：容器生命周期、登录态、重复提交、弱网和外部能力如何防守。</li><li><a href="/practice/native-mini-program-architecture">原生微信小程序架构</a>：页面、组件、请求、会话、分包和性能的稳定组织方式。</li></ul><h2 id="这套系列解决什么" tabindex="-1">这套系列解决什么 <a class="header-anchor" href="#这套系列解决什么" aria-label="Permalink to &quot;这套系列解决什么&quot;">​</a></h2><table tabindex="0"><thead><tr><th>常见困境</th><th>对应方法</th></tr></thead><tbody><tr><td>仓库很多，但没人能说清一次需求会改到哪里</td><td>建立能力地图和垂直切片清单</td></tr><tr><td>多端各自解释接口，错误处理越来越分裂</td><td>把协议、业务结果和交互策略分层</td></tr><tr><td>核心流程既写数据库又调用第三方，失败后难恢复</td><td>本地事务配合幂等、状态机、发件箱与补偿</td></tr><tr><td>Vue 2 与旧构建链升级风险高</td><td>先统一边缘层，再按业务切片迁移</td></tr><tr><td>小程序页面重复请求、登录和弹窗逻辑</td><td>把运行时能力封装成稳定适配层</td></tr><tr><td>文档很快过时</td><td>让契约测试、依赖规则和发布检查替文档守边界</td></tr><tr><td>想分享工程经验，又担心泄露项目实现</td><td>分离内部证据底稿与公开知识正文</td></tr></tbody></table><h2 id="阅读时的三个约定" tabindex="-1">阅读时的三个约定 <a class="header-anchor" href="#阅读时的三个约定" aria-label="Permalink to &quot;阅读时的三个约定&quot;">​</a></h2><p>第一，文章优先讨论“为什么这样分”，而不是把某个目录结构当成唯一答案。第二，示例刻意保持小而完整，真实项目需要再加入权限、审计、监控和迁移策略。第三，任何重构都应从可观测、可回滚的小改动开始，不能以停止业务交付为代价。</p><p>如果只准备读一篇，从<a href="/practice/full-stack-system-map">多端业务系统全景图</a>开始；如果正处理资金、库存或支付一类高风险流程，直接进入<a href="/practice/transactional-business-workflow">高一致性业务工作流</a>。</p>',15)])])}const f=t(l,[["render",d]]);export{u as __pageData,f as default};
